/**
 * Built-in node discovery for the CLI. The list of modules is generated by scripts/build-cli.mjs
 * (static imports, so it works under tsx, esbuild and Vitest alike; no import.meta.glob at runtime).
 */
import { pathToFileURL } from 'node:url';
import { isAbsolute, resolve } from 'node:path';
import { Registry } from '../engine/define';
import { nodeModules } from './generated-nodes';

export function registerBuiltinNodes(registry: Registry): string[] {
  const ids: string[] = [];
  for (const mod of nodeModules) ids.push(...registry.registerModule(mod as Record<string, unknown>));
  return ids;
}

/** `--plugin file.js`: dynamic import, then registerModule (default export or any export may be a node definition or an array of them). */
export async function loadPlugins(registry: Registry, files: string[]): Promise<string[]> {
  const ids: string[] = [];
  for (const f of files) {
    const abs = isAbsolute(f) ? f : resolve(process.cwd(), f);
    let mod: Record<string, unknown>;
    try {
      mod = (await import(/* @vite-ignore */ pathToFileURL(abs).href)) as Record<string, unknown>;
    } catch (err) {
      throw new Error(`Cannot load plugin ${f}: ${err instanceof Error ? err.message : String(err)}`);
    }
    const added = registry.registerModule(mod);
    if (added.length === 0) throw new Error(`Plugin ${f} exports no node definitions.`);
    ids.push(...added);
  }
  return ids;
}

export function createRegistry(): Registry {
  const registry = new Registry();
  registerBuiltinNodes(registry);
  return registry;
}
